import os
import torch


class Config:
    """
    Configuration class for the Right Whale Detection task.
    Centralizes all hyperparameters, file paths, and settings.
    """

    # ==========================================
    # Paths and Directories
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching intermediate data (Idea 12)
    WORKING_DIR = "./working/idea_12"

    # Submission directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure writable directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==========================================
    # Audio Parameters
    # ==========================================
    # Based on data analysis: Sample Rate is 2000Hz
    SAMPLE_RATE = 2000

    # Fixed duration of 2.0 seconds
    DURATION = 2.0
    NUM_SAMPLES = int(SAMPLE_RATE * DURATION)  # 4000 samples

    # Spectrogram extraction
    N_MELS = 128
    N_FFT = 512  # 256ms window size (good for low freq)
    HOP_LENGTH = 16  # 8ms hop size -> ~250 frames for 2.0s
    F_MIN = 10.0  # High-pass filter to remove DC offset
    F_MAX = None  # Nyquist

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    # Architecture: Multi-Band Hierarchical Coordinate-Attention ResNet-18 CRNN
    MODEL_NAME = "resnet18_ca_multiband"
    IN_CHANNELS = 1
    NUM_CLASSES = 1

    # Feature extraction settings
    USE_COORDINATE_ATTENTION = True
    USE_MULTIBAND_POOLING = True

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 20

    # Optimization
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4

    # Loss handling
    # Explicit positive class weight to handle 1:9 imbalance
    POS_WEIGHT = 9.0

    # Regularization / Augmentation
    MIXUP_ALPHA = 0.4

    # SpecAugment Constraints
    # Time Mask limit: Max 200ms.
    # With hop_length=16 and sr=2000, 1 frame = 8ms.
    # 200ms / 8ms = 25 frames. We set param to 20 to be safe.
    TIME_MASK_PARAM = 20
    FREQ_MASK_PARAM = 20

    # ==========================================
    # Compute & Debugging
    # ==========================================
    NUM_WORKERS = 2
    DEVICE = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # Debug flag to run on a small subset
    DEBUG = False
    DEBUG_SUBSET_SIZE = 100
